            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"65\" font-size=\"30\" font-weight=\"bold\" fill=\"#ffd700\" text-anchor=\"middle\">Quiz: Retrospective Wisdom</text><rect x=\"150\" y=\"200\" width=\"800\" height=\"500\" rx=\"20\" fill=\"rgba(20,20,40,0.6)\" stroke=\"#3b82f6\" stroke-width=\"3\"/><text x=\"550\" y=\"470\" font-size=\"60\" text-anchor=\"middle\">🦉</text><text x=\"550\" y=\"600\" font-size=\"22\" fill=\"#888\" text-anchor=\"middle\">flies at dusk, not dawn</text><text x=\"550\" y=\"900\" font-size=\"20\" fill=\"#f59e0b\" text-anchor=\"middle\">When does philosophical clarity arrive?</text></svg>",
